import numpy as np

def sage_layer(edges, H, W_self, W_neigh, b, normalize):
    """Self features and the mean of neighbour features, transformed separately."""
    H = np.asarray(H, float)
    n = len(H)
    A = np.zeros((n, n))
    for i, j in edges:
        A[i, j] += 1
    M = A @ H
    return np.maximum(H @ W_self + M @ W_neigh + b, 0)
